#include "schema_pg.h"

#include "schema.h"

#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

namespace schema {


// PostgreSQL 分支：与 SQLite 版本逐条对应，只替换类型与表达式。
std::vector<std::string> postgresCreateStatements() {
  return {
      "CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL)",
      "CREATE TABLE IF NOT EXISTS artist("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "name TEXT NOT NULL UNIQUE,"
      "sort_name TEXT)",
      "CREATE TABLE IF NOT EXISTS album("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "name TEXT NOT NULL,"
      "year INTEGER,"
      "cover_path TEXT,"
      "artist_key TEXT NOT NULL DEFAULT '',"
      "entity_id TEXT,"
      "UNIQUE(name, artist_key))",
      "CREATE TABLE IF NOT EXISTS genre("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "name TEXT NOT NULL UNIQUE)",
      "CREATE TABLE IF NOT EXISTS scan_root("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "path TEXT NOT NULL UNIQUE,"
      "added_at TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "last_scan TEXT,"
      "\"user\" TEXT NOT NULL DEFAULT '',"
      "pass TEXT NOT NULL DEFAULT '',"
      "name TEXT NOT NULL DEFAULT '',"
      "type TEXT NOT NULL DEFAULT '')",
      "CREATE TABLE IF NOT EXISTS track("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "root_id BIGINT NOT NULL REFERENCES scan_root(id) ON DELETE CASCADE,"
      "path TEXT NOT NULL UNIQUE,"
      "title TEXT,"
      "album_id BIGINT REFERENCES album(id) ON DELETE SET NULL,"
      "disc_no INTEGER DEFAULT 1,"
      "track_no INTEGER,"
      "duration_ms INTEGER,"
      "bitrate INTEGER,"
      "sample_rate INTEGER,"
      "channels INTEGER,"
      "format TEXT,"
      "size_bytes BIGINT,"
      "mtime BIGINT,"
      "added_at TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "play_count INTEGER NOT NULL DEFAULT 0,"
      "last_played TEXT,"
      "rating INTEGER DEFAULT 0,"
      "entity_id TEXT)",
      "CREATE TABLE IF NOT EXISTS track_artist("
      "track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE,"
      "artist_id BIGINT NOT NULL REFERENCES artist(id) ON DELETE CASCADE,"
      "position INTEGER NOT NULL DEFAULT 0,"
      "PRIMARY KEY(track_id, artist_id))",
      "CREATE TABLE IF NOT EXISTS album_artist("
      "album_id BIGINT NOT NULL REFERENCES album(id) ON DELETE CASCADE,"
      "artist_id BIGINT NOT NULL REFERENCES artist(id) ON DELETE CASCADE,"
      "position INTEGER NOT NULL DEFAULT 0,"
      "PRIMARY KEY(album_id, artist_id))",
      "CREATE TABLE IF NOT EXISTS track_genre("
      "track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE,"
      "genre_id BIGINT NOT NULL REFERENCES genre(id) ON DELETE CASCADE,"
      "PRIMARY KEY(track_id, genre_id))",
      "CREATE TABLE IF NOT EXISTS track_lyrics("
      "track_id BIGINT PRIMARY KEY REFERENCES track(id) ON DELETE CASCADE,"
      "text TEXT NOT NULL DEFAULT '',"
      "synced INTEGER NOT NULL DEFAULT 0)",
      "CREATE TABLE IF NOT EXISTS playlist("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "name TEXT NOT NULL,"
      "description TEXT,"
      "created_at TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')))",
      "CREATE TABLE IF NOT EXISTS playlist_track("
      "playlist_id BIGINT NOT NULL REFERENCES playlist(id) ON DELETE CASCADE,"
      "track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE,"
      "position INTEGER NOT NULL,"
      "PRIMARY KEY(playlist_id, position))",
      "CREATE TABLE IF NOT EXISTS play_event("
      "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "track_id BIGINT NOT NULL REFERENCES track(id) ON DELETE CASCADE,"
      "played_at TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "seconds_played INTEGER)",
      "CREATE TABLE IF NOT EXISTS entity_link("
      "link_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "entity_type TEXT NOT NULL "
      "CHECK(entity_type IN ('track','album','artist','album_artist','playlist')),"
      "created_at TEXT NOT NULL DEFAULT "
      "(to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "updated_at TEXT,"
      "UNIQUE(link_id, entity_type))",
      "CREATE TABLE IF NOT EXISTS entity_link_member("
      "member_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"
      "link_id BIGINT NOT NULL,"
      "library_id TEXT NOT NULL CHECK(length(library_id) > 0),"
      "entity_type TEXT NOT NULL "
      "CHECK(entity_type IN ('track','album','artist','album_artist','playlist')),"
      "entity_id TEXT NOT NULL CHECK(length(entity_id) > 0),"
      "confidence TEXT NOT NULL DEFAULT 'manual',"
      "verified INTEGER NOT NULL DEFAULT 1 CHECK(verified IN (0,1)),"
      "created_at TEXT NOT NULL DEFAULT "
      "(to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "updated_at TEXT,"
      "UNIQUE(library_id, entity_type, entity_id),"
      "UNIQUE(link_id, library_id),"
      "FOREIGN KEY(link_id, entity_type) "
      "REFERENCES entity_link(link_id, entity_type) ON DELETE CASCADE)",
      "CREATE TABLE IF NOT EXISTS entity_link_override("
      "link_id BIGINT NOT NULL,"
      "aspect TEXT NOT NULL "
      "CHECK(aspect IN ('metadata','lyrics','stream','artwork')),"
      "library_id TEXT NOT NULL,"
      "position INTEGER NOT NULL CHECK(position >= 0),"
      "created_at TEXT NOT NULL DEFAULT "
      "(to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),"
      "updated_at TEXT,"
      "PRIMARY KEY(link_id, aspect, library_id),"
      "UNIQUE(link_id, aspect, position),"
      "FOREIGN KEY(link_id, library_id) "
      "REFERENCES entity_link_member(link_id, library_id) ON DELETE CASCADE)",
      "CREATE INDEX IF NOT EXISTS idx_track_album ON track(album_id, disc_no, "
      "track_no)",
      "CREATE INDEX IF NOT EXISTS idx_track_added ON track(added_at)",
      "CREATE INDEX IF NOT EXISTS idx_track_root ON track(root_id)",
      "CREATE INDEX IF NOT EXISTS idx_track_artist_track ON "
      "track_artist(track_id)",
      "CREATE INDEX IF NOT EXISTS idx_track_artist_artist ON "
      "track_artist(artist_id)",
      "CREATE INDEX IF NOT EXISTS idx_album_artist_album ON "
      "album_artist(album_id)",
      "CREATE INDEX IF NOT EXISTS idx_album_artist_artist ON "
      "album_artist(artist_id)",
      "CREATE INDEX IF NOT EXISTS idx_play_event_time ON play_event(played_at)",
      "CREATE INDEX IF NOT EXISTS idx_entity_link_type ON "
      "entity_link(entity_type)",
  };
}

// entity_id 列在老库里要先 ALTER 补上，索引不能放进 createStatements()。
static void createEntityIdIndexes(db::Session &session) {
  session.exec(
      "CREATE INDEX IF NOT EXISTS idx_track_entity ON track(entity_id)");
  session.exec(
      "CREATE INDEX IF NOT EXISTS idx_album_entity ON album(entity_id)");
}


void ensurePostgresSchema(db::Session &session) {
  for (const auto &statement : postgresCreateStatements()) {
    session.exec(statement);
  }

  const auto result = session.query(sql::kSchemaVersion);
  if (result.empty()) {
    // 空库：建表语句已含 entity_id 列，直接写版本并补索引。
    session.exec("INSERT INTO schema_version(version) VALUES (" +
                 std::to_string(kVersion) + ")");
    createEntityIdIndexes(session);
    return;
  }

  std::int64_t version = 0;
  const auto &cell = result.rows.front().front();
  if (const auto *value = std::get_if<std::int64_t>(&cell.value)) {
    version = *value;
  }

  if (version == kVersion) {
    return;
  }
  if (version > kVersion) {
    throw std::runtime_error("数据库 schema 版本为 " + std::to_string(version) +
                             "，高于本程序支持的 " + std::to_string(kVersion) +
                             "，拒绝启动以免损坏数据");
  }
  // PostgreSQL 只做「加列 + 加索引」这类幂等增量升级，不重建远端库。
  if (version == 10) {
    session.exec("ALTER TABLE track ADD COLUMN IF NOT EXISTS entity_id TEXT");
    session.exec("ALTER TABLE album ADD COLUMN IF NOT EXISTS entity_id TEXT");
    createEntityIdIndexes(session);
    session.exec("UPDATE schema_version SET version = 11");
    return;
  }

  throw std::runtime_error(
      "数据库 schema 版本为 " + std::to_string(version) + "，低于本程序支持的 " +
      std::to_string(kVersion) +
      "；PostgreSQL 后端只提供 schema 10 → 11 的增量升级，更旧版本请重建空库");
}

} // namespace schema
